def _observe_site_status(self):
        """Existing owner-thread status poll, with a separate cached explanation."""
        reason, counts = 'OBSERVATION_UNVERIFIED', {}
        try:
            self._status(self._bridge.status())
        except Exception:
            self._status('UNAVAILABLE')
            reason = 'OBSERVATION_EXCEPTION'
        else:
            try:
                observation = self._bridge.session_observation()
                if (type(observation) is dict and set(observation) == {'reason', 'counts'}
                        and observation['reason'] in SESSION_REASONS
                        and type(observation['counts']) is dict
                        and set(observation['counts']).issubset(SESSION_COUNTS)
                        and all(type(item) is int and 0 <= item <= 129
                            for item in observation['counts'].values())):
                    reason, counts = observation['reason'], dict(observation['counts'])
            except Exception:
                pass
        page_metadata = dict(selected_page_closed=None, context_page_count=None,
            matching_origin_page_count=None, metadata_verified=False)
        try:
            pages = list(self._context.pages)
            selected = self._bridge.page
            if len(pages) <= 128:
                matches = 0
                for page in pages:
                    url = urlsplit(page.url)
                    if (url.scheme == 'https' and url.hostname == 'app.neurobro.ai'
                            and url.port in (None, 443)):
                        matches += 1
                closed = selected.is_closed()
                if type(closed) is bool:
                    page_metadata = dict(selected_page_closed=closed,
                        context_page_count=len(pages), matching_origin_page_count=matches,
                        metadata_verified=True)
        except Exception:
            pass
        with self.lock:
            self._session_diagnostic = dict(status=self.current_status, reason=reason,
                counts=counts, checked_at=self.checked_at, page_metadata=page_metadata,
                observed_monotonic=time.monotonic())
